package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraftforge.eventbus.api.*;import net.minecraftforge.event.level.*;import net.minecraft.server.level.*;
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID)public final class AdcEvents{
 private static final ThreadLocal<Boolean>CHECKING=ThreadLocal.withInitial(()->false);
 public static boolean mayRemove(ServerPlayer p,AdcBlockEntity b){if(!b.permitted(p))return false;CHECKING.set(true);try{for(var c:AdcGeometry.MODEL.cells){var at=AdcGeometry.MODEL.cell(b.getBlockPos(),b.facing(),c);if(!p.serverLevel().hasChunkAt(at)||!p.serverLevel().mayInteract(p,at))return false;var event=new BlockEvent.BreakEvent(p.serverLevel(),at,p.serverLevel().getBlockState(at),p);if(net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(event))return false;}return true;}finally{CHECKING.set(false);}}
 @SubscribeEvent(priority=EventPriority.HIGHEST)public static void breaking(BlockEvent.BreakEvent e){if(CHECKING.get()||!(e.getState().getBlock() instanceof AdcBlock)||!(e.getLevel()instanceof ServerLevel l)||!(e.getPlayer()instanceof ServerPlayer p))return;var b=AdcBlock.main(l,e.getPos(),e.getState());if(b==null||!mayRemove(p,b))e.setCanceled(true);}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void crowbar(net.minecraftforge.event.entity.player.PlayerInteractEvent.RightClickBlock e){var s=e.getLevel().getBlockState(e.getPos());if(s.getBlock() instanceof AdcBlock b&&e.getEntity().isShiftKeyDown()&&e.getItemStack().is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)){e.setCanceled(true);e.setCancellationResult(b.interact(s,e.getLevel(),e.getPos(),e.getEntity(),e.getHand()));}}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void removing(net.minecraftforge.event.entity.player.PlayerInteractEvent.LeftClickBlock e){if(!(e.getEntity()instanceof ServerPlayer p)||!p.isCreative()||!(e.getLevel().getBlockState(e.getPos()).getBlock()instanceof AdcBlock))return;var b=AdcBlock.main(e.getLevel(),e.getPos(),e.getLevel().getBlockState(e.getPos()));if(b!=null&&mayRemove(p,b)){e.setCanceled(true);b.remove(p,false);}}
}
